	@SuppressWarnings("deprecation")
	private static Distinct expression() {
		BindingSetAssignment values = new BindingSetAssignment();
		values.setBindingNames(Set.of("t"));
		values.setBindingSets(List.of(binding("t", A)));
		StatementPattern first = new StatementPattern(Var.of("e"), Var.of("p", P, true, true), Var.of("x"));
		StatementPattern second = new StatementPattern(Var.of("e"), Var.of("q", Q, true, true),
				Var.of("tag", TAG, true, true));
		return new Distinct(new Projection(new Join(values, new Join(first, second)),
				new ProjectionElemList(new ProjectionElem("e"))));
	}

	private static Prepared prepare(String label, EvaluationStrategy generic, LmdbNativeEvaluationStrategy strategy,
			SailDataset dataset, QueryEvaluationContext context, int kind) {
		Distinct distinct = expression();
		TupleExpr root = kind == 1 || kind == 3 || kind == 6 ? new QueryRoot(distinct) : distinct;
		root.setRuntimeTelemetryEnabled(true);
		root.setExecutionSummaryEnabled(true);
		distinct.setRuntimeTelemetryEnabled(true);
		distinct.setExecutionSummaryEnabled(true);
		QueryEvaluationStep step;
		if (kind < 2) {
			step = strategy.genericOnlyView().precompile(root, context);
		} else if (kind < 4) {
			step = generic.precompile(root, context);
		} else if (kind == 4) {
			step = LmdbNativeAggregateCompiler.tryCompile(root, context, strategy, (NativeLmdbQuerySource) dataset);
		} else {
			step = strategy.precompile(root, context);
		}
		return new Prepared(label, root, distinct, step, kind == 4);
	}

	private static QueryBindingSet binding(String name, Value value) {
		QueryBindingSet binding = new QueryBindingSet();
		binding.addBinding(name, value);
		return binding;
	}

	private static Observation observe(Prepared item, BindingSet input) {
		for (TupleExpr node : List.of(item.root(), item.distinct())) {
			node.setStringMetricActual(TelemetryMetricNames.NATIVE_EXECUTION_PATH, null);
			node.setStringMetricActual(TelemetryMetricNames.RUNTIME_PHYSICAL_PLAN, null);
		}
		long rootBefore = Math.max(0L, item.root().getLongMetricActual("nativeInvocationsActual"));
		long distinctBefore = Math.max(0L, item.distinct().getLongMetricActual("nativeInvocationsActual"));
		List<Map<String, Value>> rows = new ArrayList<>();
		List<Map<String, Value>> projected = new ArrayList<>();
		List<Map<String, Value>> caller = new ArrayList<>();
		try (var iteration = item.step().evaluate(input)) {
			while (iteration.hasNext()) {
				BindingSet result = iteration.next();
				Map<String, Value> row = new HashMap<>();
				result.forEach(binding -> row.put(binding.getName(), binding.getValue()));
				rows.add(Map.copyOf(row));
				projected.add(result.hasBinding("e") ? Map.of("e", result.getValue("e")) : Map.of());
				caller.add(result.hasBinding("t") ? Map.of("t", result.getValue("t")) : Map.of());
			}
		}
		return new Observation(List.copyOf(rows), List.copyOf(projected), List.copyOf(caller),
				Math.max(0L, item.root().getLongMetricActual("nativeInvocationsActual")) - rootBefore,
				Math.max(0L, item.distinct().getLongMetricActual("nativeInvocationsActual")) - distinctBefore,
				item.root().getStringMetricActual(TelemetryMetricNames.NATIVE_EXECUTION_PATH),
				item.distinct().getStringMetricActual(TelemetryMetricNames.NATIVE_EXECUTION_PATH),
				item.root().getStringMetricActual(TelemetryMetricNames.RUNTIME_PHYSICAL_PLAN),
				item.distinct().getStringMetricActual(TelemetryMetricNames.RUNTIME_PHYSICAL_PLAN),
				item.step().getClass().getName());
	}
